-- 관악산 추가 등산로 원천 데이터

-- 출처: 산림청 PMNTN

-- 대상 좌표계: EPSG:5179

BEGIN;

-- dataset_id는 테이블의 기본값/시퀀스로 자동 생성된다.
-- 이 파일보다 01_gwanak_seed.sql을 먼저 실행해야 한다.
-- raw_trail 행은 dataset_nm으로 자동 생성된 dataset_id를 조회하여 참조한다.
--
-- 메타데이터 확인 상태:
--   * 제공기관과 출처 URL은 dataset_id 1에서 확인된 산림청 PMNTN 정보를 따른다.
--   * base_de는 아래에 보존된 원천 데이터에서 확인했다.
--   * src_crs_cd는 01_gwanak_seed.sql의 dataset_id 1을 기준으로 추정했다.
--     저장된 raw_trail 공간정보에는 대상 좌표계 EPSG:5179가 명시되어 있다.
--   * dataset_nm과 dataset_desc에는 추정값임을 명시했다.
--   * collect_de는 스키마상 필수값이므로 01_gwanak_seed.sql의 dataset_id 1에
--     기록된 자료 등록일 2026-10-11을 추정값으로 재사용했다.
--   * file_hash는 원본 파일의 검증된 해시가 아니라 데이터셋별 원천 INSERT
--     데이터에 대한 SHA-256이며, data_ver에는 해당 해시의 앞부분을 사용했다.
--   * file_nm과 license_nm은 확인되지 않아 NULL로 입력한다.
INSERT INTO public.source_dataset (
    dataset_nm,
    origin_cd,
    data_type_cd,
    provider_nm,
    source_url,
    base_de,
    collect_de,
    src_crs_cd,
    file_nm,
    file_hash,
    license_nm,
    data_ver,
    dataset_desc
)
SELECT
    seed.dataset_nm,
    seed.origin_cd,
    seed.data_type_cd,
    seed.provider_nm,
    seed.source_url,
    seed.base_de,
    COALESCE(seed.collect_de::date, DATE '2026-10-11'),
    seed.src_crs_cd,
    seed.file_nm,
    seed.file_hash,
    seed.license_nm,
    seed.data_ver,
    seed.dataset_desc
FROM (
    VALUES
    (
        'kfs:116200604:PMNTN',
        'PUBLIC',
        'TRAIL',
        '산림청',
        'https://www.data.go.kr/data/3034022/fileData.do',
        DATE '2016-12-31',
        NULL,
        'CUSTOM_WKT',
        NULL,
        'c29be3ef310da1ca929c7ea80f38f213209002bbd99b3c5f238d7b3cfbc0f6bc',
        NULL,
        'sha256:c29be3ef310da1ca',
        '추정 dataset_nm/src_crs_cd: dataset_id 1의 산림청 PMNTN 명명·원본 CRS 규칙 적용. base_de는 raw 데이터에서 확인; collect_de는 01의 재고 등록일 2026-10-11을 추정 적용; 저장 geom CRS는 EPSG:5179; file_hash/data_ver는 이 seed의 dataset별 raw INSERT payload SHA-256 기반(원본 파일 해시 아님); 나머지 미확인 메타데이터는 NULL.'
    ),
    (
        'kfs:116200704:PMNTN',
        'PUBLIC',
        'TRAIL',
        '산림청',
        'https://www.data.go.kr/data/3034022/fileData.do',
        DATE '2016-12-31',
        NULL,
        'CUSTOM_WKT',
        NULL,
        '833b78174d42185f6f4b03c3441e7a9a2fdb1f0487b0c305bb20837e18791371',
        NULL,
        'sha256:833b78174d42185f',
        '추정 dataset_nm/src_crs_cd: dataset_id 1의 산림청 PMNTN 명명·원본 CRS 규칙 적용. base_de는 raw 데이터에서 확인; collect_de는 01의 재고 등록일 2026-10-11을 추정 적용; 저장 geom CRS는 EPSG:5179; file_hash/data_ver는 이 seed의 dataset별 raw INSERT payload SHA-256 기반(원본 파일 해시 아님); 나머지 미확인 메타데이터는 NULL.'
    ),
    (
        'kfs:116200804:PMNTN',
        'PUBLIC',
        'TRAIL',
        '산림청',
        'https://www.data.go.kr/data/3034022/fileData.do',
        DATE '2016-12-31',
        NULL,
        'CUSTOM_WKT',
        NULL,
        'f1d2ceac8812053a20af041055d5cc7448726bd19cd2c1c7ff9b91ab6ee4382d',
        NULL,
        'sha256:f1d2ceac8812053a',
        '추정 dataset_nm/src_crs_cd: dataset_id 1의 산림청 PMNTN 명명·원본 CRS 규칙 적용. base_de는 raw 데이터에서 확인; collect_de는 01의 재고 등록일 2026-10-11을 추정 적용; 저장 geom CRS는 EPSG:5179; file_hash/data_ver는 이 seed의 dataset별 raw INSERT payload SHA-256 기반(원본 파일 해시 아님); 나머지 미확인 메타데이터는 NULL.'
    ),
    (
        'kfs:116200904:PMNTN',
        'PUBLIC',
        'TRAIL',
        '산림청',
        'https://www.data.go.kr/data/3034022/fileData.do',
        DATE '2016-12-31',
        NULL,
        'CUSTOM_WKT',
        NULL,
        'ae048a962fe8e6edf99bac2759036be2db53057a62478f15b8a8ec53e3a1d214',
        NULL,
        'sha256:ae048a962fe8e6ed',
        '추정 dataset_nm/src_crs_cd: dataset_id 1의 산림청 PMNTN 명명·원본 CRS 규칙 적용. base_de는 raw 데이터에서 확인; collect_de는 01의 재고 등록일 2026-10-11을 추정 적용; 저장 geom CRS는 EPSG:5179; file_hash/data_ver는 이 seed의 dataset별 raw INSERT payload SHA-256 기반(원본 파일 해시 아님); 나머지 미확인 메타데이터는 NULL.'
    )
) AS seed (
    dataset_nm,
    origin_cd,
    data_type_cd,
    provider_nm,
    source_url,
    base_de,
    collect_de,
    src_crs_cd,
    file_nm,
    file_hash,
    license_nm,
    data_ver,
    dataset_desc
)
WHERE NOT EXISTS (
    SELECT 1
    FROM public.source_dataset AS existing
    WHERE existing.dataset_nm = seed.dataset_nm
);

-- 아래의 각 하위 쿼리는 정확히 하나의 source_dataset 행이 조회되어야 한다.
-- 메타데이터가 없거나 중복된 경우 임의의 데이터셋에 등산로를 연결하지 않고
-- 시드 실행이 실패하도록 구성했다.


